<template>
 <div class="app-container queues">
  <div class="heading"><div><h2>消息队列</h2><p>管理业务队列、消费资源和运行告警。共享队列由平台管理员统一维护。</p></div><div><el-button v-if="links.grafana" size="small" @click="external(links.grafana)">Grafana 趋势</el-button><el-button v-if="links.prometheus" size="small" @click="external(links.prometheus)">Prometheus 告警</el-button><el-button size="small" aria-label="刷新队列" icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></div></div>
  <el-alert title="暂停业务处理同时约束 MQ 消费和数据库补偿；在途任务允许完成。配置保存后，以各实例回报的实际状态为准。" type="info" show-icon :closable="false"/>
  <div class="cards"><div><span>已登记业务队列</span><strong>{{ rows.length }}</strong></div><div><span>配置已生效</span><strong>{{ rows.filter(r=>['RUNNING','PAUSED'].includes(r.effective_state)).length }}</strong></div><div><span>在线消费者</span><strong>{{ rows.reduce((v,r)=>v+Number(r.actual_consumers||0),0) }}</strong></div><div><span>触发中告警</span><strong :class="{danger:firing.length}">{{ firing.length }}</strong></div></div>
  <div class="caption">每 15 秒刷新缓存结果 · {{ refreshed || '尚未刷新' }}<span>共享队列展示全局运行数据，消息任务按当前登录公司查看</span></div>
  <el-tabs v-model="tab"><el-tab-pane label="业务队列" name="queues"><el-table :data="rows" v-loading="loading">
   <el-table-column label="业务队列" min-width="260"><template slot-scope="s"><el-link type="primary" @click="open(s.row,'instances')">{{ s.row.title }}</el-link><div class="muted mono">{{ s.row.queue_name }}</div><div class="muted">{{ service(s.row.service_code) }} · quorum · 版本 {{ s.row.revision }}</div></template></el-table-column>
   <el-table-column label="运行 / 生效" width="150"><template slot-scope="s"><el-tag size="small" :type="tone(s.row.effective_state)">{{ state(s.row.effective_state) }}</el-tag><div class="muted">期望：{{ state(s.row.desired_mode) }}</div><div v-if="s.row.instances.some(i=>!i.online && !i.retired)" class="warning">存在离线实例</div></template></el-table-column>
   <el-table-column label="消费资源" min-width="150"><template slot-scope="s"><div>每实例 {{ s.row.concurrency }} 并发</div><div class="muted">预取 {{ s.row.prefetch }} / 消费者</div><div class="muted">重试上限 {{ s.row.retry_limit }} 次</div><div class="muted">在线 {{ s.row.actual_consumers }} · 在途 {{ s.row.active_work }}</div></template></el-table-column>
   <el-table-column label="代理队列" min-width="170"><template slot-scope="s"><div>待消费 {{ metric(s.row,'ready') }} · 未确认 {{ metric(s.row,'unacked') }}</div><div class="muted">代理死信 {{ metric(s.row,'dead') }} · 台账待处理 {{ s.row.quarantine_pending || 0 }}</div><el-button type="text" size="mini" @click="open(s.row,'dead')">核查死信</el-button><div class="muted" v-if="s.row.broker.fresh">投递 {{ rate(s.row,'publish_rate') }}/s · 确认 {{ rate(s.row,'ack_rate') }}/s</div><div v-else class="warning">{{ s.row.broker.sampled_at?'数据过期 · '+s.row.broker.sampled_at:'尚无采集数据' }}</div></template></el-table-column>
   <el-table-column label="业务待办" min-width="180"><template slot-scope="s"><div>到期未处理 {{ businessMetric(s.row,'due') }}</div><div class="muted">最长等待 {{ businessMetric(s.row,'oldest_due_sec') }} 秒</div><div class="muted">待投递 {{ businessMetric(s.row,'pending_publish') }}</div><div v-if="!businessFresh(s.row)" class="warning">业务指标过期或尚未采集</div></template></el-table-column>
   <el-table-column label="操作" width="260" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row,'instances')">运行详情</el-button><el-button type="text" @click="open(s.row,'config')">配置</el-button><el-button type="text" @click="tasks(s.row)">消息任务</el-button><el-button type="text" v-hasPermi="['oms:queue:edit']" @click="mode(s.row)">{{ s.row.desired_mode==='RUNNING'?'暂停处理':'恢复处理' }}</el-button></template></el-table-column>
  </el-table></el-tab-pane>
  <el-tab-pane label="消费实例" name="instances"><instance-table :rows="instances"/></el-tab-pane>
  <el-tab-pane :label="'当前告警（'+alerts.length+'）'" name="alerts"><alert-table :rows="alerts" @task="alertTask"/></el-tab-pane></el-tabs>
  <el-drawer :title="detail?detail.title+' · 队列管理':'队列管理'" :visible.sync="visible" size="920px" append-to-body><div class="detail" v-if="detail" v-loading="detailLoading">
   <div class="detail-bar"><el-tag :type="tone(detail.effective_state)">{{ state(detail.effective_state) }}</el-tag><span>配置版本 {{ detail.revision }} · {{ detail.queue_name }}</span><el-button size="small" @click="reloadDetail">刷新状态</el-button><el-button size="small" type="primary" plain @click="tasks(detail)">查看消息任务</el-button></div>
   <el-tabs v-model="detailTab"><el-tab-pane label="配置" name="config">
    <el-alert title="消费并发为每实例上限，MQ 与补偿共用处理额度。每实例总并发上限：订单服务 16，渠道服务 12；修改后会等待在途任务完成并应用配置。" type="info" :closable="false"/>
    <el-form :model="form" label-position="top" class="config" size="small">
     <h3>消费资源</h3><div class="form-grid"><el-form-item label="期望运行状态"><el-radio-group v-model="form.desired_mode"><el-radio-button label="RUNNING">运行</el-radio-button><el-radio-button label="PAUSED">暂停处理</el-radio-button></el-radio-group></el-form-item><el-form-item label="消费并发 / 实例"><el-input-number v-model="form.concurrency" :min="1" :max="8"/></el-form-item><el-form-item label="每消费者预取数"><el-input-number v-model="form.prefetch" :min="1" :max="50"/></el-form-item></div>
     <h3>失败重试与补偿</h3><div class="form-grid"><el-form-item label="临时失败处理次数上限"><el-input-number v-model="form.retry_limit" :min="1" :max="20"/></el-form-item><el-form-item label="初始重试间隔 / 秒"><el-input-number v-model="form.retry_base_sec" :min="5" :max="300"/></el-form-item><el-form-item label="最大重试间隔 / 秒"><el-input-number v-model="form.retry_max_sec" :min="form.retry_base_sec" :max="3600"/></el-form-item><el-form-item label="到期后等待多久补偿 / 秒"><el-input-number v-model="form.compensate_after_sec" :min="30" :max="3600"/></el-form-item><el-form-item label="每公司每轮补偿批量"><el-input-number v-model="form.compensate_batch" :min="1" :max="20"/></el-form-item></div>
     <template v-if="['PRODUCT_PULL','EXCHANGE_PULL','REFUND_FLOW','REFUND_PLATFORM','REFUND_API_PULL','REFUND_API_DETAIL'].includes(detail.business_type)"><h3>平台调用额度</h3><p class="muted">商品、换货与退款平台任务按应用、店铺跨服务共享额度，采用相关队列配置中的较低上限；额度不足时保留断点等待。</p><div class="form-grid"><el-form-item label="每应用调用上限 / 秒"><el-input-number v-model="form.app_rate" :min="1" :max="20"/></el-form-item><el-form-item label="每店铺调用上限 / 秒"><el-input-number v-model="form.shop_rate" :min="1" :max="20"/></el-form-item></div></template>
     <h3>告警阈值</h3><div class="form-grid"><el-form-item label="待消费消息数量"><el-input-number v-model="form.alarm_backlog" :min="1" :max="100000"/></el-form-item><el-form-item label="到期任务最长等待 / 秒"><el-input-number v-model="form.alarm_due_sec" :min="30" :max="86400"/></el-form-item><el-form-item label="最近5分钟失败比例 / %"><el-input-number v-model="form.alarm_failure_pct" :min="1" :max="100"/></el-form-item></div><p class="muted">失败率至少有 10 条完成样本才评估；主动暂停期间抑制积压、消费者缺失与到期等待告警。</p>
     <el-form-item label="修改依据（必填）"><el-input v-model.trim="reason" type="textarea" :rows="2" maxlength="255" show-word-limit placeholder="说明本次调参、暂停或恢复的原因"/></el-form-item>
     <el-button type="primary" :loading="saving" v-hasPermi="['oms:queue:edit']" @click="save">保存配置并下发</el-button>
    </el-form></el-tab-pane>
    <el-tab-pane label="消费实例" name="instances"><instance-table :rows="detail.instances"/></el-tab-pane>
    <el-tab-pane label="告警记录" name="history"><alert-table :rows="detail.alert_history.map(r=>({...r,business_type:detail.business_type}))" @task="alertTask"/></el-tab-pane>
    <el-tab-pane label="死信核查" name="dead"><dead-letter-table v-if="detailTab==='dead'" :type="detail.business_type" :service="detail.service_code" @task="tasks"/></el-tab-pane>
    <el-tab-pane label="操作记录" name="operations"><el-table :data="detail.operations" empty-text="暂无配置变更"><el-table-column prop="create_time" label="时间" width="190"/><el-table-column prop="revision" label="版本" width="70"/><el-table-column prop="actor" label="操作人" width="100"/><el-table-column prop="reason" label="修改依据"/></el-table></el-tab-pane>
    <el-tab-pane label="队列结构" name="topology"><el-descriptions border :column="1"><el-descriptions-item v-for="key in ['service_code','business_type','queue_name','dead_queue','exchange','routing_key','queue_type']" :key="key" :label="topologyLabels[key]">{{ detail[key] }}</el-descriptions-item></el-descriptions><p class="muted">结构由登记的业务类型确定，运行配置不会重建队列或修改消息内容。</p></el-tab-pane>
   </el-tabs>
  </div></el-drawer>
 </div>
</template>
<script>
import request from '@/utils/request'
import { stateNames } from './queuePresentation'
import InstanceTable from './InstanceTable'
import AlertTable from './AlertTable'
import DeadLetterTable from './DeadLetterTable'
import { alertTarget } from './messagePresentation'
export default{name:'QueueManagement',components:{InstanceTable,AlertTable,DeadLetterTable},data(){return{rows:[],links:{},loading:false,refreshed:'',tab:'queues',timer:null,alive:true,visible:false,detail:null,detailLoading:false,detailTab:'config',form:{},reason:'',saving:false,topologyLabels:{service_code:'所属服务',business_type:'业务类型',queue_name:'工作队列',dead_queue:'死信队列',exchange:'交换机',routing_key:'路由键',queue_type:'队列类型'}}},computed:{instances(){return this.rows.flatMap(r=>r.instances)},alerts(){const seen=new Set();return this.rows.flatMap(r=>r.alerts).filter(r=>{const k=r.business_type+':'+r.rule_code;if(seen.has(k))return false;seen.add(k);return true})},firing(){return this.alerts.filter(r=>r.state==='FIRING')}},created(){this.load()},activated(){this.alive=true;this.schedule()},deactivated(){this.alive=false;clearTimeout(this.timer)},beforeDestroy(){this.alive=false;clearTimeout(this.timer)},methods:{
 state(s){return stateNames[s]||s},tone(s){return s==='RUNNING'?'success':s==='NO_INSTANCES'||s==='ERROR'?'danger':s==='PAUSED'?'info':'warning'},service(s){return s==='channel'?'渠道服务':'订单服务'},metric(r,k){return r.broker.data && r.broker.data[k]!==undefined?r.broker.data[k]:'—'},rate(r,k){const n=this.metric(r,k);return n==='—'?n:Number(n).toFixed(1)},businessFresh(r){return Number(r.business.sampled_ms)>Date.now()-65000},businessMetric(r,k){return r.business[k]===undefined?'—':r.business[k]},external(url){window.open(url,'_blank','noopener,noreferrer')},
 schedule(){clearTimeout(this.timer);if(this.alive)this.timer=setTimeout(()=>this.load(true),15000)},async load(quiet=false){if(!quiet)this.loading=true;try{const r=await request({url:'/system/mqQueues'});if(!this.alive)return;this.rows=r.data.queues;this.links=r.data;this.refreshed=new Date().toLocaleTimeString()}finally{this.loading=false;this.schedule()}},
 async open(row,tab='instances'){this.visible=true;this.detailLoading=true;this.detail=null;this.detailTab=tab;try{const r=await request({url:'/system/mqQueues/'+row.business_type});this.detail=r.data;this.form={...r.data};this.reason=''}finally{this.detailLoading=false}},async reloadDetail(){if(!this.detail)return;const r=await request({url:'/system/mqQueues/'+this.detail.business_type});this.detail=r.data;this.load(true)},alertTask(row){const target=alertTarget(row);if(!target)return;if(target.dead){const queue=this.rows.find(r=>r.business_type===row.business_type);if(queue)this.open(queue,'dead')}else{this.visible=false;this.$router.push(target)}},tasks(row){this.visible=false;this.$router.push({path:'/monitor/messages',query:{service:row.service_code,type:row.business_type,...(row.event?{event:row.event}:{}),...(row.focus?{focus:row.focus}:{})}})},
 async save(){if(!this.reason){this.$message.warning('请填写本次修改依据');return}this.saving=true;try{const r=await request({url:'/system/mqQueues/'+this.detail.business_type,method:'put',data:{...this.form,reason:this.reason}});this.form={...r.data};this.reason='';this.$message.success('配置已保存，等待各实例回报生效状态');await this.reloadDetail()}finally{this.saving=false}},
 async mode(row){try{const paused=row.desired_mode==='RUNNING';const {value}=await this.$prompt(paused?'暂停后 MQ 消费与数据库补偿都停止领取新任务，在途任务允许完成。请填写暂停原因。':'恢复后继续处理原有待办。请填写恢复依据。',paused?'暂停业务处理':'恢复业务处理',{inputType:'textarea',inputValidator:v=>!!v&&v.trim().length>0&&v.length<=255,inputErrorMessage:'请填写255字以内的依据'});await request({url:'/system/mqQueues/'+row.business_type,method:'put',data:{...row,desired_mode:paused?'PAUSED':'RUNNING',reason:value.trim()}});this.$message.success('指令已保存，请查看实例生效状态');this.load()}catch(e){if(e!=='cancel'&&e!=='close')console.error('Queue control unavailable')}}
}}
</script>
<style scoped>
.heading,.caption,.detail-bar{display:flex;justify-content:space-between;align-items:center;gap:12px}.heading{margin-bottom:18px}.heading h2{margin:0;font-size:20px;color:#263c54}.heading p,.muted,.caption{color:#8492a6;font-size:12px;line-height:1.8}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.cards>div{border:1px solid #e4eaf2;border-radius:8px;padding:18px;background:#f8fafc}.cards span{display:block;color:#8190a5;font-size:13px}.cards strong{display:block;margin-top:8px;font-size:28px;color:#263c54}.cards .danger{color:#dc5b55}.caption{margin-bottom:12px}.mono{font-family:Consolas,monospace;word-break:break-all}.warning{color:#b77d15;font-size:12px;line-height:1.7}.detail{padding:0 24px 32px}.detail-bar{flex-wrap:wrap;justify-content:flex-start;font-size:12px;color:#7c8c9e;margin-bottom:15px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0 18px}.config h3{font-size:15px;color:#304a64;border-bottom:1px solid #edf0f5;padding-bottom:10px;margin-top:24px}.config ::v-deep .el-form-item__label{padding-bottom:2px}.config ::v-deep .el-input-number{width:180px}
</style>
